const config = $('Safety Configuration').first().json;
const now = new Date();
const dayKey = new Intl.DateTimeFormat('en-CA', {
  timeZone: config.timezone || 'Asia/Manila',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(now);

const leads = $items('Fetch Active Hot Warm Leads')
  .map((item) => item.json)
  .filter((lead) => lead.id && lead.workspace_id);

const activities = $items('Fetch Lead Activities')
  .map((item) => item.json)
  .filter((activity) => activity.lead_id && activity.occurred_at);

const tasks = $items('Fetch Existing Tasks')
  .map((item) => item.json)
  .filter((task) => task.lead_id);

const stages = $items('Fetch Pipeline Stages')
  .map((item) => item.json)
  .filter((stage) => stage.id);

const latestActivityByLead = new Map();
for (const activity of activities) {
  const timestamp = new Date(activity.occurred_at).getTime();
  const previous = latestActivityByLead.get(activity.lead_id) || 0;
  if (Number.isFinite(timestamp) && timestamp > previous) {
    latestActivityByLead.set(activity.lead_id, timestamp);
  }
}

const stageTypeById = new Map(stages.map((stage) => [stage.id, stage.stage_type]));
const openTaskLeadIds = new Set(
  tasks.filter((task) => task.status === 'open').map((task) => task.lead_id),
);
const taskDescriptions = tasks
  .map((task) => String(task.description || ''))
  .filter(Boolean);

const candidates = [];
for (const lead of leads) {
  const stageType = lead.pipeline_stage_id
    ? stageTypeById.get(lead.pipeline_stage_id)
    : 'open';

  if (stageType === 'won' || stageType === 'lost') continue;
  if (openTaskLeadIds.has(lead.id)) continue;

  const thresholdHours = lead.routing_status === 'Hot'
    ? Number(config.hot_stale_hours || 2)
    : Number(config.warm_stale_hours || 24);

  const fallbackTouch = new Date(lead.updated_at || lead.created_at || 0).getTime();
  const lastTouchMs = latestActivityByLead.get(lead.id) || fallbackTouch;
  if (!Number.isFinite(lastTouchMs)) continue;

  const inactiveHours = (now.getTime() - lastTouchMs) / 3600000;
  if (inactiveHours < thresholdHours) continue;

  const marker = '[AUTO-FOLLOW-UP:v1:' +
    lead.public_id + ':' + dayKey + ':' + lead.routing_status + ']';

  if (taskDescriptions.some((description) => description.includes(marker))) {
    continue;
  }

  const dueHours = lead.routing_status === 'Hot' ? 2 : 24;
  const dueAt = new Date(now.getTime() + dueHours * 3600000).toISOString();

  candidates.push({
    json: {
      create_task: true,
      write_enabled: config.write_enabled === true,
      workspace_id: lead.workspace_id,
      lead_id: lead.id,
      lead_public_id: lead.public_id,
      lead_name: lead.name || lead.email || lead.public_id,
      routing_status: lead.routing_status,
      title: 'Follow up with ' + (lead.name || lead.email || lead.public_id),
      description:
        'Auto-created by Follow-Up Engine v1. ' +
        lead.routing_status + ' lead inactive for ' +
        Math.floor(inactiveHours) + ' hours. ' + marker,
      priority: lead.routing_status === 'Hot' ? 'high' : 'medium',
      due_at: dueAt,
      inactivity_hours: Math.floor(inactiveHours),
      idempotency_marker: marker,
    },
  });
}

if (candidates.length === 0) {
  return [{
    json: {
      create_task: false,
      write_enabled: config.write_enabled === true,
      message: 'No eligible stale Hot or Warm leads found.',
      scanned_leads: leads.length,
    },
  }];
}

return candidates;

const rows = $input.all().map((item) => item.json);
return [{
  json: {
    ok: true,
    created_count: rows.length,
    task_ids: rows.map((row) => row.public_id || row.id).filter(Boolean),
    message: 'Internal follow-up tasks created. No email, SMS, or calendar action was performed.',
  },
}];

const rows = $input.all().map((item) => item.json);
const eligible = rows.filter((row) => row.create_task === true);
return [{
  json: {
    ok: true,
    write_enabled: rows.some((row) => row.write_enabled === true),
    eligible_count: eligible.length,
    message: eligible.length
      ? 'Dry-run only: eligible follow-up tasks were identified but not written.'
      : (rows[0]?.message || 'No follow-up action required.'),
    candidates: eligible.map((row) => ({
      lead_public_id: row.lead_public_id,
      routing_status: row.routing_status,
      priority: row.priority,
      due_at: row.due_at,
      idempotency_marker: row.idempotency_marker,
    })),
  },
}];
